try { if(!(Test-Path work/_info)){& "$ModelSimBin/vlib.exe" work};$s=@('rtl/control_protocol_pkg.sv','rtl/performance_event_pkg.sv','rtl/loop_event_ram.sv','rtl/loop_event_store.sv','rtl/loop_scheduler.sv','rtl/command_mailbox.sv','rtl/control_csr.sv','rtl/mode_manager.sv','rtl/performance_event_fifo_wrapper.sv','rtl/performance_event_ingress.sv','rtl/performance_event_router.sv','rtl/input_event_mux.sv','rtl/loop_control_plane.sv','rtl/performance_event_voice_bridge.sv','rtl/mgc3130_voice_mixer.sv','rtl/loop_audio_path.sv','sim/tb_loop_audio_path.sv')|%{Join-Path $root $_};& "$ModelSimBin/vlog.exe" -sv -work work @s *> compile.log;if($LASTEXITCODE){Get-Content compile.log;throw 'compile failed'};& "$ModelSimBin/vsim.exe" -c -l audio_path.log work.tb_loop_audio_path -do 'run 1 ms; quit -code 0 -f' *> console.log;if($LASTEXITCODE -or !(Select-String -Path audio_path.log -SimpleMatch 'tb_loop_audio_path PASS' -Quiet)){Get-Content audio_path.log;throw 'audio path failed'};'loop audio path PASS'}finally{Pop-Location}
